export const simulationFrames: Airframe[] = [lightJet, twinEngineJet, heavyJet, agileJet, pioneerTrainer, biplane, heavyBomber];

for (const frame of simulationFrames) COMBATANT_CONFIGS[frame.id] = playerCombatant(frame);

export function simulationFrame(id: string) {
  const frame = simulationFrames.find(frame => frame.id === id);
  if (!frame) throw new Error(`Unknown simulation fixture ${id}`);
  return frame;
}
